#!/usr/bin/env python3
"""Curate short paraphrases of verified examples; do not redistribute textbook text."""
import json,pathlib,hashlib
ROOT=pathlib.Path(__file__).resolve().parents[1]
BOOK='https://doi.org/10.1007/978-981-15-5204-5'; PMS='https://cran.r-project.org/web/packages/pmsampsize/pmsampsize.pdf'
tasks=[];oracles=[]
def add(id,tier,family,split,prompt,method,params,metric='sample_size',unit='participants_total',source_value=None,kind='textbook_worked_example',locator=None,notes=None,pilot=False):
 if method.startswith('riley'):
  params.update({'precision_confidence':0.95,'rsquared_difference':0.05})
  prompt += ' Precision uses 95% confidence and maximum absolute apparent-versus-adjusted R-squared difference 0.05 (Nagelkerke scale for binary/survival).'
  if method=='riley_continuous':
   params.update({'residual_sd_mmoe':1.1,'intercept_mmoe':1.1})
   prompt += ' Target residual-SD multiplicative margin of error 1.1 and mean-outcome multiplicative margin of error 1.1.'
  else:
   params.update({'risk_halfwidth':0.05})
   prompt += ' Target average outcome-risk absolute margin of error 0.05; for survival verify this precision at the returned package sample size.'
 design={'method':method,'alpha':params.get('alpha',.05),'alternative':params.get('alternative','omnibus' if method in ['linear_regression','one_way_anova','factorial_anova','rm_between','rm_within','rm_interaction'] else 'not_applicable' if method.startswith('riley') else 'one_sided'),'allocation_ratio':params.get('allocation_ratio',1 if unit=='participants_per_group' or method.startswith('rm') else None)}
 if method.startswith('riley'):design['alpha']=None
 t={'id':id,'tier':tier,'family':family,'split':split,'pilot':pilot,'question':prompt,'response_contract':{'metric':metric,'unit':unit,'design_keys':['method','alpha','alternative','allocation_ratio']},'provenance':{'kind':kind,'url':PMS if kind=='primary_method_illustration' else BOOK if kind=='textbook_worked_example' else 'https://doi.org/10.1002/sim.7992' if method.startswith('riley') else 'https://doi.org/10.1007/978-981-15-5204-5_7','locator':locator,'verified_from':'Provided local Verma OCR (book contents) plus publisher metadata' if kind=='textbook_worked_example' else 'CRAN pmsampsize 1.1.3 manual, Examples, pp.5–6' if kind=='primary_method_illustration' else 'New constructed parameter variant; no published worked answer','notes':notes or ''}}
 tasks.append(t);oracles.append({'id':id,'published_source_value':source_value,'method':method,'parameters':params,'expected_design':design,'metric':metric,'unit':unit,'absolute_tolerance':0.0001 if metric=='power' else 0,'reference_method':'Independent specified noncentral distribution / Riley criteria; crosschecked with published answer and R package where applicable'})
# T1: source families are grouped; fixed n power problems test a different requested output.
add('pa26-t1-one-sample-n',1,'verma6.1','development','For a normally distributed outcome, test a mean increase of 0.2 units with SD 0.5 using a one-sided one-sample t test at alpha 0.05. What minimum integer number of participants achieves 80% power?','one_sample_t',{'d':.4,'power':.8},source_value=41,locator='Chapter 6, Illustration 6.1, pp.63–65')
add('pa26-t1-one-sample-power',1,'verma6.1','development','For a normally distributed outcome, use a one-sided one-sample t test at alpha 0.05 to detect a 0.2-unit mean increase with SD 0.5. With 25 participants, what is the power (decimal)?','one_sample_t',{'d':.4,'n':25},metric='power',unit='probability',source_value=.6173,locator='Chapter 6, Illustration 6.1, pp.63–65')
add('pa26-t1-two-sample-n',1,'verma6.3','evaluation','Compare two independent normal means with equal variances and 1:1 allocation. The expected difference is 4.3 dBA and common SD is 7.8 dBA. For a one-sided pooled t test at alpha 0.05, what minimum integer number per group achieves 80% power?','two_sample_t',{'d':4.3/7.8,'power':.8},unit='participants_per_group',source_value=42,locator='Chapter 6, Illustration 6.3, pp.69–72',pilot=True)
add('pa26-t1-two-sample-power',1,'verma6.3','evaluation','Compare two independent normal means with equal variances. The expected difference is 4.3 dBA and common SD is 7.8 dBA. With 32 participants per group, what is the power of a one-sided pooled t test at alpha 0.05?','two_sample_t',{'d':4.3/7.8,'n':32,'allocation_ratio':1},metric='power',unit='probability',source_value=.704,locator='Chapter 6, Illustration 6.3, pp.69–72')
add('pa26-t1-paired-n',1,'verma6.4','evaluation','Plan a paired t test for a 3-kg mean weight reduction. Baseline SD is 5 kg, follow-up SD is 5.5 kg, and the within-person correlation is 0.5. For a one-sided test at alpha 0.05, what minimum integer number of participants achieves 80% power?','paired_t',{'d':3/(25+30.25-27.5)**.5,'power':.8},source_value=21,locator='Chapter 6, Illustration 6.4, pp.72–74',pilot=True)
add('pa26-t1-proportion-precision',1,'verma3.6','development','Using the normal approximation with the exact standard normal 97.5th percentile and no finite population correction, how many participants are needed to estimate a proportion of 0.70 with a two-sided 95% confidence interval of half-width 0.03? Round upward.','proportion_precision',{'p':.7,'margin':.03,'alternative':'two_sided'},source_value=897,locator='Chapter 3, Illustration 3.6, pp.38–39')
# T2: linear/general linear models, source families kept together.
add('pa26-t2-regression-n',2,'verma7.1','development','For a fixed linear model with an intercept and 3 predictors, test whether population R-squared differs from zero. Anticipated multiple correlation is 0.30. At alpha 0.05, what minimum integer total sample size gives 90% power using the noncentral F test?','linear_regression',{'u':3,'p':3,'f2':.09/.91,'power':.9},source_value=148,locator='Chapter 7, Illustration 7.1, pp.90–94')
add('pa26-t2-regression-power',2,'verma7.1','development','For a fixed linear model with an intercept and 3 predictors, test R-squared against zero. Anticipated multiple correlation is 0.30. With 80 participants, what is the noncentral F-test power at alpha 0.05?','linear_regression',{'u':3,'p':3,'f2':.09/.91,'n':80},metric='power',unit='probability',source_value=.6238,locator='Chapter 7, Illustration 7.1, pp.90–94')
add('pa26-t2-anova-n',2,'verma7.4','evaluation','Plan a balanced one-way fixed effects ANOVA with 3 independent normal groups and common variance. Population eta-squared is 0.06. At alpha 0.05, what minimum integer participants per group yields 80% power for the omnibus F test?','one_way_anova',{'groups':3,'f2':.06/.94,'power':.8},unit='participants_per_group',source_value=52,locator='Chapter 7, Illustration 7.4, pp.100–102',pilot=True)
add('pa26-t2-anova-power',2,'verma7.4','evaluation','A balanced one-way fixed effects ANOVA has 3 independent normal groups, common variance, total sample size 75, and population eta-squared 0.08. What is the omnibus F-test power at alpha 0.05?','one_way_anova',{'groups':3,'f2':.08/.92,'n':75,'allocation_ratio':1},metric='power',unit='probability',source_value=.6031,locator='Chapter 7, Illustration 7.4, pp.100–102')
add('pa26-t2-factorial-age',2,'verma7.5','evaluation','Plan a balanced 3-by-2 fixed factorial ANOVA with all 6 cells independent, a full interaction model, and common variance. Test the 3-level factor main effect (2 numerator degrees of freedom). Partial eta-squared is 0.06. At alpha 0.05, what minimum integer participants per cell gives 80% power?','factorial_anova',{'cells':6,'u':2,'f2':.06/.94,'power':.8},unit='participants_per_cell',source_value=26,locator='Chapter 7, Illustration 7.5, pp.103–105',pilot=True)
add('pa26-t2-factorial-gender',2,'verma7.5','evaluation','Plan a balanced 3-by-2 fixed factorial ANOVA with independent normal observations and common variance, fitting all 6 cell means. Test the 2-level factor main effect (1 numerator degree of freedom). Partial eta-squared is 0.06. At alpha 0.05, what minimum integer participants per cell gives 80% power?','factorial_anova',{'cells':6,'u':1,'f2':.06/.94,'power':.8},unit='participants_per_cell',source_value=21,locator='Chapter 7, Illustration 7.5, pp.103–105')
# T3: specify covariance, estimand and exact planned test, rather than an unspecified mixed model.
add('pa26-t3-rm-between',3,'verma7.6','evaluation','Plan a balanced repeated-measures ANOVA for the between-group main effect with two groups and 3 repeated measurements per participant. At every occasion, marginal SD is 2.5 and the group means are 51 and 49. Assume multivariate normal observations, compound symmetry with correlation 0.5, no missing data and no group-by-time interaction. For the group effect use the subject-level average with a pooled t test (equivalently the between-group F test), alpha 0.05 two-sided. What minimum integer participants per group achieves 80% power?','rm_between',{'groups':2,'measurements':3,'f2':.16,'rho':.5,'power':.8,'alternative':'two_sided'},unit='participants_per_group',source_value=18,locator='Chapter 7, Illustration 7.6, pp.105–107',pilot=True)
add('pa26-t3-rm-within',3,'verma7.7','evaluation','Plan a one-group repeated-measures ANOVA with 3 time points, multivariate normal data, compound symmetry correlation 0.5, and no missing data. For the within-time omnibus effect use the univariate F test with sphericity epsilon 1. The G*Power population effect is partial eta-squared 0.08 before the correlation adjustment (f-squared = eta-squared/(1-eta-squared)). At alpha 0.05, what minimum total integer sample size achieves 90% power?','rm_within',{'groups':1,'measurements':3,'f2':.08/.92,'rho':.5,'epsilon':1,'power':.9},source_value=26,locator='Chapter 7, Illustration 7.7, pp.107–109',pilot=True)
add('pa26-t3-rm-interaction',3,'verma7.8','development','Plan a balanced two-group, three-time-point repeated-measures ANOVA for the group-by-time interaction. Assume multivariate normal data, compound symmetry correlation 0.5, sphericity epsilon 1 and no missing data. The G*Power partial eta-squared is 0.06 before the correlation adjustment. Using the univariate F test at alpha 0.05, what minimum integer participants per group achieves 85% power?','rm_interaction',{'groups':2,'measurements':3,'f2':.06/.94,'rho':.5,'epsilon':1,'power':.85},unit='participants_per_group',source_value=16,locator='Chapter 7, Illustration 7.8, pp.109–111')
add('pa26-t3-rm-variant',3,'constructed-rm-between','development','Plan a two-group random-intercept Gaussian study with 4 observations per participant. The marginal SD is 1, intraclass correlation is 0.4, the constant mean group difference is 0.45, groups are equally allocated and there is no missing data. Analyze each participant average with a two-sided pooled t test at alpha 0.05. What minimum integer participants per group achieves 90% power?','rm_between',{'groups':2,'measurements':4,'f2':(.45/2)**2,'rho':.4,'power':.9,'alternative':'two_sided'},unit='participants_per_group',kind='constructed_task',locator='Predeclared parameter variant of compound-symmetry subject-average design')
# T4: keep source status explicit; no claim these examples come from Verma.
add('pa26-t4-riley-binary',4,'pms-manual-binary','evaluation','Calculate the minimum total development sample size for a binary clinical prediction model using the Riley criteria as implemented by pmsampsize 1.1.3. There are 24 candidate predictor parameters (excluding intercept), prevalence 0.174 and anticipated adjusted Cox-Snell R-squared 0.288. Use shrinkage 0.90 and the package default precision criteria; do not use events-per-variable rules.','riley_binary',{'parameters':24,'prevalence':.174,'rsquared':.288,'shrinkage':.9},source_value=662,kind='primary_method_illustration',locator='Manual pp.5, binary example; Riley et al., Statistics in Medicine, doi:10.1002/sim.7992',pilot=True)
add('pa26-t4-riley-survival',4,'pms-manual-survival','evaluation','Calculate the minimum total development sample size for a survival prediction model using the Riley criteria implemented by pmsampsize 1.1.3. There are 30 candidate predictor parameters, adjusted Cox-Snell R-squared 0.051, overall event rate 0.065 per person-year, mean follow-up 2.07 years and prediction horizon 2 years. Use shrinkage 0.90 and default package criteria.','riley_survival',{'parameters':30,'rsquared':.051,'rate':.065,'meanfup':2.07,'timepoint':2,'shrinkage':.9},source_value=5143,kind='primary_method_illustration',locator='Manual pp.5–6, survival example based on Riley et al., BMJ 2020, doi:10.1136/bmj.m441',pilot=True)
add('pa26-t4-riley-continuous',4,'pms-manual-continuous','development','Calculate the minimum total development sample size for a continuous prediction model using the Riley criteria implemented by pmsampsize 1.1.3. There are 25 candidate predictor parameters, anticipated adjusted R-squared 0.20, outcome mean 1.9 and outcome SD 0.6. Use shrinkage 0.90 and default package precision criteria, including intercept multiplicative margin of error 1.1.','riley_continuous',{'parameters':25,'rsquared':.2,'intercept':1.9,'sd':.6,'shrinkage':.9,'mmoe':1.1},source_value=918,kind='primary_method_illustration',locator='Manual p.6, continuous example; Riley et al., doi:10.1002/sim.7993')
add('pa26-t4-riley-variant',4,'constructed-riley-binary','development','Use pmsampsize 1.1.3 Riley binary development criteria with 10 candidate predictor parameters, prevalence 0.20, anticipated adjusted Cox-Snell R-squared 0.12 and shrinkage 0.95. Use default absolute precision criteria. What minimum total sample size is required?','riley_binary',{'parameters':10,'prevalence':.2,'rsquared':.12,'shrinkage':.95},kind='constructed_task',locator='Predeclared parameter variant of Riley binary criteria')
manifest={'suite_version':'2.0.0','curation_date':'2026-10-01','tiers':{'1':'Basic mean/proportion calculations','2':'Fixed general linear models','3':'Repeated/structured Gaussian designs','4':'Clinical prediction model development'},'task_count':len(tasks),'tasks':tasks}
(ROOT/'audited/tasks.json').write_text(json.dumps(manifest,indent=2)+'\n');(ROOT/'audited/reference-specifications.json').write_text(json.dumps(oracles,indent=2)+'\n')
print(f'Wrote {len(tasks)} tasks, {sum(t["pilot"] for t in tasks)} pilot tasks')
